from math import gcd
from typing import List


class Solution:
    def maxLength(self, nums: List[int]) -> int:
        n = len(nums)
        best = 0
        for i in range(n):
            product = 1
            g = 0
            l = 1
            for j in range(i, n):
                product *= nums[j]
                if product > 1000:
                    break
                g = gcd(g, nums[j])
                l = l * nums[j] // gcd(l, nums[j])
                if product == l * g:
                    best = max(best, j - i + 1)
        return best

